package android.widget;import android.content.Context;import android.view.ViewGroup;public class LinearLayout extends ViewGroup {public static final int HORIZONTAL=0,VERTICAL=1;public int orientation,gravity;public LinearLayout(Context c){super(c);}public void setOrientation(int o){orientation=o;emit("orientation",o);}public void setGravity(int g){gravity=g;emit("gravity",g);}public static class LayoutParams extends ViewGroup.MarginLayoutParams {public float weight;public int gravity;public LayoutParams(int w,int h){super(w,h);}public LayoutParams(int w,int h,float e){super(w,h);weight=e;}}}